-- SENTINEL collector store (Cloudflare D1). Large JSON values are split across parts.
CREATE TABLE IF NOT EXISTS blobs (k TEXT NOT NULL, part INTEGER NOT NULL, v TEXT NOT NULL, at INTEGER NOT NULL, PRIMARY KEY (k, part));
CREATE TABLE IF NOT EXISTS tasks (id TEXT PRIMARY KEY, next INTEGER NOT NULL DEFAULT 0, lease INTEGER NOT NULL DEFAULT 0, last INTEGER, ok INTEGER, err TEXT, ms INTEGER, runs INTEGER NOT NULL DEFAULT 0, fails INTEGER NOT NULL DEFAULT 0);
